(() => {
  const props = ['color', 'backgroundColor', 'borderTopColor', 'borderRightColor', 'borderBottomColor', 'borderLeftColor', 'outlineColor', 'fill', 'stroke', 'textDecorationColor', 'boxShadow'];
  const widths = { borderTopColor: 'borderTopWidth', borderRightColor: 'borderRightWidth', borderBottomColor: 'borderBottomWidth', borderLeftColor: 'borderLeftWidth', outlineColor: 'outlineWidth' };
  const bad = {};
  let n = 0;
  for (const el of document.querySelectorAll('body, body *')) {
    if (!el.getClientRects().length) continue;
    for (const ps of [null, '::before', '::after']) {
      const cs = getComputedStyle(el, ps);
      if (ps && (cs.content === 'none' || cs.content === 'normal')) continue;
      if (cs.visibility === 'hidden' || cs.display === 'none') continue;
      for (const p of props) {
        if (widths[p] && parseFloat(cs[widths[p]]) === 0) continue;
        if (p === 'outlineColor' && cs.outlineStyle === 'none') continue;
        const v = cs[p];
        if (!v || v === 'none') continue;
        for (const m of v.matchAll(/rgba?\(([^)]+)\)/g)) {
          const c = m[1].split(',').map(parseFloat);
          if (c.length > 3 && c[3] === 0) continue;
          n++;
          if (Math.max(c[0], c[1], c[2]) - Math.min(c[0], c[1], c[2]) > 0) {
            const key = (el.className && el.className.baseVal === undefined ? '.' + String(el.className).trim().split(/\s+/).join('.') : el.tagName) + (ps || '') + ' ' + p + ' ' + m[0];
            bad[key] = (bad[key] || 0) + 1;
          }
        }
      }
    }
  }
  const keys = Object.keys(bad);
  return 'colors=' + n + ' notgray=' + keys.length + (keys.length ? ' ' + keys.slice(0, 8).join(' | ') : '');
})()

